const { writeFileSync, readFileSync, accessSync, constants } = await import('node:fs');
if (!globalThis.input || typeof globalThis.input.png_path !== 'string') {
  throw new Error('Missing required input png_path');
}
const pngPath = globalThis.input.png_path;
try { accessSync(pngPath, constants.R_OK); } catch (e) { throw new Error('Cannot read PNG file at ' + pngPath); }
globalThis.pngPath = pngPath;

const { readFile, writeFile } = await import('node:fs').then(m => m.promises);
const upngMod = await import('@pdf-lib/upng');
const upng = upngMod.default || upngMod;
const { PDFDocument } = await import('pdf-lib');
const pngBytes = await readFile(globalThis.pngPath);
// Optional: decode with upng to ensure validity (not strictly needed for pdf-lib)
try { upng.decode(pngBytes.buffer); } catch (_) { /* ignore decode errors, pdf-lib will handle */ }
const pdfDoc = await PDFDocument.create();
const pngImage = await pdfDoc.embedPng(pngBytes);
const { width, height } = pngImage.scale(1);
const page = pdfDoc.addPage([width, height]);
page.drawImage(pngImage, { x: 0, y: 0, width, height });
const pdfBytes = await pdfDoc.save();
const outPath = globalThis.pngPath.replace(/\.png$/i, '.pdf');
await writeFile(outPath, pdfBytes);
globalThis.pdfPath = outPath;
